    {
        gameObject.SetActive(false);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireCube(Center, roomSize);

        if (config != null)
        {
            var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
            foreach (var dir in dirs)
            {
                if (config.HasDoor(dir))
                {
                    Gizmos.color = Color.yellow;
                    Gizmos.DrawSphere(GetDoorWorldPosition(dir), 0.3f);
                }
            }
        }
    }
}

using UnityEngine;

/// <summary>
/// 房间门 — 挂载在每个门 GO 上。
/// 普通门：Trigger 检测玩家 → 切换房间。
/// 隐藏墙：清房后 openTrigger 启用但不放行玩家，子弹命中 N 次后墙壁破碎，显示门。
/// 无连接的门：直接隐藏，不出现墙壁贴图。
/// </summary>
public class RoomPortal : MonoBehaviour
{
    [Header("门配置")]
    public DoorDirection direction;
    public int targetRoomId = -1;

    [Header("组件引用")]
    [Tooltip("门 GO 的 SpriteRenderer")]
    public SpriteRenderer doorSprite;

    [Tooltip("开门/子弹检测的 Trigger Collider")]
    public Collider2D openTrigger;

    [Tooltip("关门/隐藏墙时激活的阻挡物")]
    public GameObject doorBlocker;

    [Header("触发设置")]
    public string targetTag = "Player";

    private bool _locked;
    private bool _hidden;       // 无连接，永久隐藏
    private bool _breakable;
    private int _hiddenWallHP;
    private int _currentHP;

    private void Awake()
    {
        if (doorSprite == null) doorSprite = GetComponent<SpriteRenderer>();
        if (openTrigger == null) openTrigger = GetComponent<Collider2D>();
        if (openTrigger != null) openTrigger.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        // 可破坏墙壁：检测子弹
        if (_breakable && other.TryGetComponent<Projectile>(out var proj))
        {
            OnBulletHit(proj);
            return;
        }

        // 隐藏墙未破坏前不放行玩家 (_locked 为 true)
        if (_locked) return;

        // 正常的门传送
        if (targetRoomId < 0) return;
        if (!other.CompareTag(targetTag)) return;
        if (MapManager.Instance == null) return;
        if (other.GetComponent<PlayerStats>() == null) return;

        MapManager.Instance.SwitchRoom(targetRoomId, direction);
    }

    private void OnBulletHit(Projectile proj)
    {
        _currentHP--;
        Destroy(proj.gameObject);

        if (_currentHP <= 0)
            BreakWall();
    }

    private void BreakWall()
    {
        _breakable = false;
        _hiddenWallHP = 0;
        _locked = false;

        // 隐藏墙破坏后显示门
        if (doorBlocker != null) doorBlocker.SetActive(false);
        if (doorSprite != null) doorSprite.enabled = true;
        if (openTrigger != null) openTrigger.enabled = true;

        Debug.Log($"RoomPortal: 隐藏墙已破坏, 门已显示 (方向: {direction})");
    }

    /// <summary>设置为隐藏墙</summary>
    public void SetAsBreakableWall(int hp)
    {
        if (hp <= 0) return;
        _hiddenWallHP = hp;
        _currentHP = hp;
        _breakable = false;
        _locked = true;

        if (doorSprite != null) doorSprite.enabled = false;
        if (openTrigger != null) openTrigger.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }

    /// <summary>激活可破坏状态（清房后调用）：启用 openTrigger 接收子弹</summary>
    public void SetBreakable()
    {
        if (_hiddenWallHP <= 0 || _breakable) return;
        _breakable = true;
        if (openTrigger != null) openTrigger.enabled = true;
        Debug.Log($"RoomPortal: 隐藏墙可破坏 (方向: {direction}, HP: {_currentHP})");
    }

    public bool IsBreakable => _breakable;
    public int HiddenWallHP => _hiddenWallHP;

    /// <summary>锁定/解锁门</summary>
    public void SetLocked(bool locked)
    {
        if (_hidden) return;
        _locked = locked;

        if (openTrigger != null)
            openTrigger.enabled = !locked;

        if (doorSprite != null)
            doorSprite.enabled = !locked;

        if (doorBlocker != null)
            doorBlocker.SetActive(locked);
    }

    /// <summary>永久隐藏门（无连接房间），不显示墙壁贴图</summary>
    public void HideAsWall()
    {
        targetRoomId = -1;
        _hidden = true;
        _breakable = false;
        _hiddenWallHP = 0;

        if (openTrigger != null) openTrigger.enabled = false;
        if (doorSprite != null) doorSprite.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(false);
    }
}

using UnityEngine;

/// <summary>
/// 怪物生成器 — 可独立使用或挂载在房间上
/// 负责从配置中读取怪物池并按权重生成敌人
/// </summary>
public class EnemySpawner : MonoBehaviour
{
    [Header("生成配置")]
    [Tooltip("引用房间配置 (为空则使用下方手动配置)")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public EnemySpawnEntry[] manualEntries;
    public int manualMinEnemies = 1;
    public int manualMaxEnemies = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    /// <summary>存活怪物追踪</summary>
    public event System.Action OnAllEnemiesDefeated;

    private int _aliveCount;
    private bool _hasSpawned;

    /// <summary>开始生成</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var entries = roomConfig != null ? roomConfig.enemyPool : 
            (manualEntries != null ? new System.Collections.Generic.List<EnemySpawnEntry>(manualEntries) : null);

        if (entries == null || entries.Count == 0) return;

        int min = roomConfig != null ? roomConfig.minEnemies : manualMinEnemies;
        int max = roomConfig != null ? roomConfig.maxEnemies : manualMaxEnemies;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;
        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 洗牌生成点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        for (int i = 0; i < count; i++)
        {
            var entry = PickWeighted(entries);
            if (entry == null || entry.enemyPrefab == null) continue;

            var point = spawnPoints[indices[i]];
            var enemy = Instantiate(entry.enemyPrefab, point.position, Quaternion.identity, transform);

            RegisterEnemy(enemy);
        }
    }

    /// <summary>
    /// 注册一个敌人到房间计数，并监听其死亡/同化事件。
    /// 生成器直接生成的敌人与亡语（死亡分裂）爆出的敌人都通过此方法计数，
    /// 否则亡语怪不计入计数会导致房间门提前开启。
    /// </summary>
    public void RegisterEnemy(GameObject enemy)
    {
        if (enemy == null) return;

        _aliveCount++;

        // 监听死亡和同化（使用 IEnemy 接口以便兼容重构后的敌人）
        if (enemy.TryGetComponent<IEnemy>(out var ienemy))
        {
            ienemy.OnDied += () =>
            {
                _aliveCount--;
                if (_aliveCount <= 0)
                    OnAllEnemiesDefeated?.Invoke();
            };
            ienemy.OnAssimilated += (_) =>
            {
                _aliveCount--;
                if (_aliveCount <= 0)
                    OnAllEnemiesDefeated?.Invoke();
            };
        }
    }

    private EnemySpawnEntry PickWeighted(System.Collections.Generic.List<EnemySpawnEntry> entries)
    {
        float total = 0f;
        foreach (var e in entries) total += e.weight;
        if (total <= 0f) return entries[0];

        float roll = Random.Range(0f, total);
        float cumulative = 0f;
        foreach (var e in entries)
        {
            cumulative += e.weight;
            if (roll <= cumulative) return e;
        }
        return entries[^1];
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具生成器 — 从道具池中随机生成道具
/// </summary>
public class ItemSpawner : MonoBehaviour
{
    [Header("道具池")]
    [Tooltip("引用房间配置")]
    public RoomConfig roomConfig;

    [Tooltip("手动配置 — 仅在没有 roomConfig 时使用")]
    public GameObject[] manualItemPool;
    public int manualMinItems = 1;
    public int manualMaxItems = 3;

    [Header("生成点")]
    public Transform[] spawnPoints;

    private bool _hasSpawned;

    /// <summary>生成道具</summary>
    public void Spawn()
    {
        if (_hasSpawned) return;
        _hasSpawned = true;

        var library = ItemsLibrary.Instance;
        if (library == null)
        {
            Debug.LogWarning("[ItemSpawner] ItemsLibrary 未找到，跳过生成");
            return;
        }

        // 确定池和权重
        var pool = (roomConfig != null && roomConfig.itemPool != null && roomConfig.itemPool.Count > 0)
            ? roomConfig.itemPool
            : (manualItemPool != null && manualItemPool.Length > 0 ? new List<GameObject>(manualItemPool) : null);
        var weights = (roomConfig != null && roomConfig.qualityWeights != null && roomConfig.qualityWeights.Length > 0)
            ? roomConfig.qualityWeights
            : null;
        var filter = ItemPoolFilter.GetPlayerItemManager();

        int min = roomConfig != null ? roomConfig.minItems : manualMinItems;
        int max = roomConfig != null ? roomConfig.maxItems : manualMaxItems;
        int total = Random.Range(min, max + 1);
        int available = spawnPoints != null ? spawnPoints.Length : 0;

        if (available == 0) return;

        int count = Mathf.Min(total, available);

        // 随机洗牌生成点
        var indices = new int[available];
        for (int i = 0; i < available; i++) indices[i] = i;
        for (int i = indices.Length - 1; i > 0; i--)
        {
            int j = Random.Range(0, i + 1);
            (indices[i], indices[j]) = (indices[j], indices[i]);
        }

        var picked = library.GetRandomItemPrefabs(count, pool, weights, filter);
        for (int i = 0; i < picked.Count; i++)
        {
            if (picked[i] == null) continue;
            Instantiate(picked[i], spawnPoints[indices[i]].position, Quaternion.identity, transform);
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 小地图 UI — 在界面右上角显示房间和走廊的关系图。
/// 从 MapManager.RoomGraph 读取数据，绘制到 RawImage 的 Texture2D 上。
/// </summary>
[RequireComponent(typeof(RawImage))]
public class MinimapUI : MonoBehaviour
{
    [Header("小地图尺寸")]
    [SerializeField] private int _textureSize = 256;
    [SerializeField] private float _uiWidth = 200f;
    [SerializeField] private float _uiHeight = 200f;

    [Header("绘制参数")]
    [SerializeField] private int _corridorWidth = 4;
    [SerializeField] [Range(0.2f, 1f)] private float _roomDisplayScale = 0.55f;

    [Header("房间颜色")]
    [SerializeField] private Color _startColor = new(0.3f, 0.8f, 0.3f);
    [SerializeField] private Color _normalColor = new(0.5f, 0.5f, 0.5f);
    [SerializeField] private Color _treasureColor = new(1f, 0.84f, 0f);
    [SerializeField] private Color _bossColor = new(0.8f, 0.2f, 0.2f);
    [SerializeField] private Color _shopColor = new(0.3f, 0.6f, 1f);
    [SerializeField] private Color _exitColor = new(0.6f, 0.2f, 0.8f);
    [SerializeField] private Color _hiddenColor = new(0.85f, 0.5f, 0.1f);
    [SerializeField] private Color _explorableColor = new(0.25f, 0.25f, 0.25f, 0.45f);
    [SerializeField] private Color _explorableBorderColor = new(0.18f, 0.18f, 0.18f, 0.55f);
    [SerializeField] private Color _explorableCorridorColor = new(0.18f, 0.18f, 0.18f, 0.35f);
    [SerializeField] private Color _currentBorderColor = Color.white;
    [SerializeField] private Color _corridorColor = new(0.28f, 0.28f, 0.28f, 0.7f);
    [SerializeField] private Color _bgColor = new(0f, 0f, 0f, 0.6f);

    private RawImage _rawImage;
    private Texture2D _texture;
    private int _currentRoomId = -1;
    private System.Collections.Generic.HashSet<int> _visitedRoomIds = new();

    /// <summary>是否隐藏地图（地西泮道具效果）。为 true 时所有房间显示为未探索状态</summary>
    public static bool HideMap = false;

    /// <summary>是否全图点亮（荧光蛋白 GFP）。为 true 时所有房间显示为已探索</summary>
    public static bool RevealAllMap = false;

    private void Awake()
    {
        _rawImage = GetComponent<RawImage>();
        if (_rawImage == null)
            _rawImage = gameObject.AddComponent<RawImage>();

        ResizeUI();
        CreateTexture();
    }

    private void Start()
    {
        // 订阅房间切换事件
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted += OnRoomSwitchCompleted;

        // 尝试立即绘制；如果地图还没生成，延迟一帧再试
        TryDraw();

        if (_currentRoomId < 0)
            StartCoroutine(DelayedDraw());
    }

    private IEnumerator DelayedDraw()
    {
        yield return null;
        TryDraw();
    }

    private void OnDestroy()
    {
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted -= OnRoomSwitchCompleted;

        if (_texture != null)
            Destroy(_texture);
    }

    private void OnRoomSwitchCompleted(int newRoomId)
    {
        _visitedRoomIds.Add(newRoomId);
        _currentRoomId = newRoomId;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph != null)
            DrawMap(graph);
    }

    // ==================== 公开方法 ====================

    [ContextMenu("Refresh")]
    public void Refresh()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null) return;
        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    // ==================== 内部绘制 ====================

    private void ResizeUI()
    {
        var rt = GetComponent<RectTransform>();
        if (rt == null) rt = gameObject.AddComponent<RectTransform>();
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _uiWidth);
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _uiHeight);
    }

    private void CreateTexture()
    {
        _texture = new Texture2D(_textureSize, _textureSize, TextureFormat.RGBA32, false);
        _texture.filterMode = FilterMode.Point;
        _texture.wrapMode = TextureWrapMode.Clamp;
        _rawImage.texture = _texture;
    }

    private void TryDraw()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null || graph.nodes.Count == 0) return;

        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    private void DrawMap(RoomGraph graph)
    {
        if (_texture == null) CreateTexture();
        if (graph == null || graph.nodes.Count == 0) return;

        // 荧光蛋白：全图点亮，把所有房间标记为已探索
        if (RevealAllMap)
        {
            foreach (var node in graph.nodes)
                _visitedRoomIds.Add(node.roomId);
        }

        // 1. 计算世界边界
        float minX = float.MaxValue, maxX = float.MinValue;
        float minY = float.MaxValue, maxY = float.MinValue;

        foreach (var node in graph.nodes)
        {
            Vector2 half = node.config.roomSize * 0.5f;
            minX = Mathf.Min(minX, node.worldPosition.x - half.x);
            maxX = Mathf.Max(maxX, node.worldPosition.x + half.x);
            minY = Mathf.Min(minY, node.worldPosition.y - half.y);
            maxY = Mathf.Max(maxY, node.worldPosition.y + half.y);
        }

        float worldW = maxX - minX;
        float worldH = maxY - minY;
        if (worldW < 0.001f || worldH < 0.001f) return;

        // 2. 计算缩放比例 (保持宽高比，并预留边距)
        float texPadding = _textureSize * 0.06f;
        float usableSize = _textureSize - texPadding * 2f;
        float scale = Mathf.Min(usableSize / worldW, usableSize / worldH);
        float offsetX = (usableSize - worldW * scale) / 2f;
        float offsetY = (usableSize - worldH * scale) / 2f;

        // 世界坐标 -> 像素坐标
        int WorldToPixelX(float wx) => Mathf.RoundToInt(texPadding + offsetX + (wx - minX) * scale);
        int WorldToPixelY(float wy) => Mathf.RoundToInt(texPadding + offsetY + (wy - minY) * scale);

        // 3. 清空纹理
        Color[] pixels = new Color[_textureSize * _textureSize];
        for (int i = 0; i < pixels.Length; i++)
            pixels[i] = _bgColor;

        // 4. 计算"可探索"房间: 未访问但与已探索房间相邻的房间 (隐藏房除外)
        // 地西泮效果：HideMap=true 时所有房间都视为未探索
        var explorableIds = new System.Collections.Generic.HashSet<int>();
        if (HideMap)
        {
            // 隐藏地图模式：所有非隐藏房都显示为可探索灰色
            foreach (var node in graph.nodes)
            {
                if (node.roomType == RoomType.Hidden) continue;
                explorableIds.Add(node.roomId);
            }
        }
        else
        {
            foreach (var node in graph.nodes)
            {
                if (_visitedRoomIds.Contains(node.roomId)) continue;
                if (node.roomType == RoomType.Hidden) continue;
                foreach (var conn in node.connections)
                {
                    if (_visitedRoomIds.Contains(conn.Key))
                    {
                        explorableIds.Add(node.roomId);
                        break;
                    }
                }
            }
        }

        // 5. 画走廊 (隐藏房不参与可探索连线)
        foreach (var node in graph.nodes)
        {
            foreach (var conn in node.connections)
            {
                if (node.roomId >= conn.Key) continue;
                var neighbor = graph.GetNode(conn.Key);
                if (neighbor == null) continue;

                // 隐藏房不显示在可探索状态
                if (!_visitedRoomIds.Contains(node.roomId) && node.roomType == RoomType.Hidden) continue;
                if (!_visitedRoomIds.Contains(neighbor.roomId) && neighbor.roomType == RoomType.Hidden) continue;

                bool aVisited = HideMap ? false : _visitedRoomIds.Contains(node.roomId);
                bool bVisited = HideMap ? false : _visitedRoomIds.Contains(neighbor.roomId);
                bool aExplorable = explorableIds.Contains(node.roomId);
                bool bExplorable = explorableIds.Contains(neighbor.roomId);

                bool draw = (aVisited || bVisited) && (aVisited || bVisited || aExplorable || bExplorable);
                if (!draw) continue;

                Color lineColor = (aVisited && bVisited) ? _corridorColor : _explorableCorridorColor;

                Vector2 centerA = node.worldPosition;
                Vector2 centerB = neighbor.worldPosition;
                DrawThickLine(pixels,
                    WorldToPixelX(centerA.x), WorldToPixelY(centerA.y),
                    WorldToPixelX(centerB.x), WorldToPixelY(centerB.y),
                    lineColor, _corridorWidth);
            }
        }

        // 6. 画可探索房间: Boss/Exit 用真实颜色，其余用灰色
        foreach (var node in graph.nodes)
        {
            if (!explorableIds.Contains(node.roomId)) continue;

            bool isBossOrExit = node.roomType == RoomType.Boss || node.roomType == RoomType.Exit;
            Color fillColor = isBossOrExit ? GetRoomColor(node.roomType) : _explorableColor;
            Color borderColor = isBossOrExit
                ? Color.Lerp(GetRoomColor(node.roomType), Color.black, 0.3f)
                : _explorableBorderColor;

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                    pixels[y * _textureSize + x] = isBorder ? borderColor : fillColor;
                }
            }
        }

        // 7. 画已探索房间 (HideMap 时跳过，所有房间在步骤6已画为灰色可探索)
        if (!HideMap)
        {
        foreach (var node in graph.nodes)
        {
            if (!_visitedRoomIds.Contains(node.roomId)) continue;

            Color roomColor = GetRoomColor(node.roomType);

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);

                    if (isBorder)
                    {
                        pixels[y * _textureSize + x] = Color.Lerp(roomColor, Color.black, 0.3f);
                    }
                    else
                    {
                        pixels[y * _textureSize + x] = roomColor;
                    }
                }
            }

            // 8. 高亮当前房间边框
            if (node.roomId == _currentRoomId)
            {
                for (int y = py1; y <= py2; y++)
                {
                    for (int x = px1; x <= px2; x++)
                    {
                        bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                        if (isBorder)
                            pixels[y * _textureSize + x] = _currentBorderColor;
                    }
                }
            }
        }
        } // end if (!HideMap)

        // HideMap 模式下仍然高亮当前房间边框，让玩家知道自己在哪
        if (HideMap)
        {
            var currentNode = graph.GetNode(_currentRoomId);
            if (currentNode != null)
            {
                Vector2 half = currentNode.config.roomSize * 0.5f * _roomDisplayScale;
                int px1 = ClampPixel(WorldToPixelX(currentNode.worldPosition.x - half.x));
                int py1 = ClampPixel(WorldToPixelY(currentNode.worldPosition.y - half.y));
                int px2 = ClampPixel(WorldToPixelX(currentNode.worldPosition.x + half.x));
                int py2 = ClampPixel(WorldToPixelY(currentNode.worldPosition.y + half.y));

                for (int y = py1; y <= py2; y++)
                {
                    for (int x = px1; x <= px2; x++)
                    {
                        bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                        if (isBorder)
                            pixels[y * _textureSize + x] = _currentBorderColor;
                    }
                }
            }
        }

        _texture.SetPixels(pixels);
        _texture.Apply();
    }

    private int ClampPixel(int val)
    {
        return Mathf.Clamp(val, 0, _textureSize - 1);
    }

    private void DrawThickLine(Color[] pixels, int x0, int y0, int x1, int y1, Color color, int thickness)
    {
        int dx = Mathf.Abs(x1 - x0);
        int dy = Mathf.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int half = thickness / 2;

        while (true)
        {
            // 画中心点周围的方形
            for (int dy2 = -half; dy2 <= half; dy2++)
            {
                for (int dx2 = -half; dx2 <= half; dx2++)
                {
                    int tx = x0 + dx2;
                    int ty = y0 + dy2;
                    if (tx >= 0 && tx < _textureSize && ty >= 0 && ty < _textureSize)
                        pixels[ty * _textureSize + tx] = color;
                }
            }

            if (x0 == x1 && y0 == y1) break;

            int e2 = 2 * err;
            if (e2 > -dy) { err -= dy; x0 += sx; }
            if (e2 < dx) { err += dx; y0 += sy; }
        }
    }

    private Color GetRoomColor(RoomType type)
    {
        return type switch
        {
            RoomType.Start => _startColor,
            RoomType.Normal => _normalColor,
            RoomType.Treasure => _treasureColor,
            RoomType.Boss => _bossColor,
            RoomType.Shop => _shopColor,
            RoomType.Exit => _exitColor,
            RoomType.Hidden => _hiddenColor,
            _ => Color.gray
        };
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// 房间摄像机控制器 — 固定房间视角 + 房间切换平滑滑动。
/// 挂载在 MainCamera 上。
/// 
/// 行为:
/// - 在房间中: 摄像机固定在房间中心，orthographicSize = 根据房间大小自动计算
/// - 房间切换: 平滑滑动到新房间中心 (0.5s)
/// - 过渡期间通知 MapManager 锁定玩家输入
/// </summary>
/// <remarks>
/// DefaultExecutionOrder 低于 CameraShake：确保本组件的 LateUpdate 先执行（锁定位置），
/// CameraShake 的 LateUpdate 随后叠加振动偏移，避免振动被覆盖。
/// </remarks>
[DefaultExecutionOrder(100)]
[RequireComponent(typeof(Camera))]
public class RoomCameraController : MonoBehaviour
{
    [Header("过渡设置")]
    [Tooltip("房间切换过渡时长 (秒)")]
    public float transitionDuration = 0.5f;

    [Tooltip("过渡曲线")]
    public AnimationCurve transitionCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);

    [Header("视角设置")]
    [Tooltip("摄像机 Orthographic Size 与房间高度的比例 (1.0 = 正好包住房间内高，1.2 = 含墙壁+门边距)")]
    public float sizeScale = 1.2f;

    [Tooltip("最小 Orthographic Size")]
    public float minOrthoSize = 5f;

    [Tooltip("最大 Orthographic Size")]
    public float maxOrthoSize = 25f;

    private Camera _cam;
    private Vector3 _targetPosition;
    private float _targetOrthoSize;
    private bool _isTransitioning;
    private Coroutine _transitionCoroutine;
    private RoomRoot _currentRoom;

    private void Awake()
    {
        _cam = GetComponent<Camera>();
        _targetPosition = transform.position;
        _targetOrthoSize = _cam.orthographicSize;
    }

    private void LateUpdate()
    {
        if (!_isTransitioning)
        {
            // 固定模式：直接锁定在目标位置
            transform.position = _targetPosition;
            _cam.orthographicSize = _targetOrthoSize;
        }
    }

    /// <summary>切换摄像机到目标房间</summary>
    /// <param name="room">目标房间</param>
    /// <param name="onComplete">过渡完成回调</param>
    public void MoveToRoom(RoomRoot room, System.Action onComplete = null)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z; // 保持 Z 轴

        // 计算合适的 Orthographic Size
        float targetSize = CalculateOrthoSize(room);

        if (transitionDuration <= 0f || _targetPosition == roomCenter)
        {
            // 瞬间切换
            _targetPosition = roomCenter;
            _targetOrthoSize = targetSize;
            onComplete?.Invoke();
            return;
        }

        // 平滑过渡
        if (_transitionCoroutine != null)
            StopCoroutine(_transitionCoroutine);
        _transitionCoroutine = StartCoroutine(TransitionRoutine(roomCenter, targetSize, onComplete));
    }

    /// <summary>根据房间大小计算合适的 Orthographic Size。</summary>
    /// <remarks>房间视觉范围 = roomSize + 四周墙壁(0.5×2=1)。取高宽中较严的方向，确保全覆盖。</remarks>
    private float CalculateOrthoSize(RoomRoot room)
    {
        // 含墙壁的完整视觉尺寸
        float visualW = room.roomSize.x + 1f;
        float visualH = room.roomSize.y + 1f;

        // Orthographic Size = half height → 纵向覆盖需要 visualH/2
        float sizeFromHeight = visualH * 0.5f * sizeScale;
        // 横向覆盖需要 visualW/2 / aspect
        float sizeFromWidth = visualW * 0.5f * sizeScale / _cam.aspect;
        float size = Mathf.Max(sizeFromHeight, sizeFromWidth);
        return Mathf.Clamp(size, minOrthoSize, maxOrthoSize);
    }

    /// <summary>平滑过渡协程</summary>
    private IEnumerator TransitionRoutine(Vector3 targetPos, float targetSize, System.Action onComplete)
    {
        _isTransitioning = true;

        Vector3 startPos = transform.position;
        float startSize = _cam.orthographicSize;

        float elapsed = 0f;

        while (elapsed < transitionDuration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / transitionDuration);
            float curveT = transitionCurve.Evaluate(t);

            transform.position = Vector3.Lerp(startPos, targetPos, curveT);
            _cam.orthographicSize = Mathf.Lerp(startSize, targetSize, curveT);

            yield return null;
        }

        // 最终值精确设置
        transform.position = targetPos;
        _cam.orthographicSize = targetSize;
        _targetPosition = targetPos;
        _targetOrthoSize = targetSize;

        _isTransitioning = false;
        onComplete?.Invoke();
    }

    /// <summary>立即跳转到房间 (无过渡)</summary>
    public void SnapToRoom(RoomRoot room)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z;

        transform.position = roomCenter;
        _targetPosition = roomCenter;
        _targetOrthoSize = CalculateOrthoSize(room);
        _cam.orthographicSize = _targetOrthoSize;
    }

    public RoomRoot CurrentRoom => _currentRoom;
    public bool IsTransitioning => _isTransitioning;
}

